/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_categories_after_insert` AFTER INSERT ON `tbc_categories` FOR EACH ROW BEGIN
    DECLARE rol_usuario VARCHAR(50);
    DECLARE usuario_real VARCHAR(255);

    SET usuario_real = USER();

    SELECT FROM_USER
    INTO rol_usuario
    FROM mysql.role_edges
    WHERE TO_USER = SUBSTRING_INDEX(usuario_real, '@', 1)
      AND TO_HOST = '%'
    LIMIT 1;

    IF rol_usuario IS NULL THEN
        SET rol_usuario = 'Sin rol';
    END IF;

    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_description,
        operation_status
    )
    VALUES (
        'tbc_categories',
        'Create',
        usuario_real,
        CONCAT(
            'El usuario: ', SUBSTRING_INDEX(usuario_real, '@', 1),
            ' (', rol_usuario, ')',
            ' ha creado la categoría. ID=', NEW.ID,
            ', nombre=', NEW.name,
            ', descripción=', COALESCE(NEW.description, 'NULL'),
            ', categoría superior=', COALESCE(NEW.sup_id_category, 'NULL'),
            ', estado=', NEW.status + 0
        ),
        b'1'
    );
END */;;
